// Trajectory projection and comparison (protocol/trajectory.ts, adapters/pi/trajectory.ts,
// runtime/contracts/trajectory.ts, cli/trajectory.ts). Self-contained: every input is a committed fixture loaded into
// a scratch durable store and read back through the read-only CLI path. No Pi, network or key is used.
//
// - REAL Pi 1.0.1 recordings (research/pi-conformance/1.0.1/lifecycle/): each against itself, completes vs
//   stop-mid-turn, and killed-and-resumed.
// - FAKE hostile recordings (tests/fixtures/trajectory/fake-pi/, regenerated by record-fake.ts beside them): each
//   differs from `baseline` in one controlled way. Every comparison's digest is pinned here.
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, describe, expect, it, vi } from "vitest";
import { piToolArgsDigestV0 } from "../adapters/pi/mapping.ts";
import { projectPiTrajectoryV0 } from "../adapters/pi/trajectory.ts";
import { trajectoryDiffCommand, trajectoryFromStoreV0, trajectoryShowCommand } from "../cli/trajectory.ts";
import type { EndoEventV0 } from "../protocol/event.ts";
import {
	ENDO_TRAJECTORY_COMPARISON_RULES_V0,
	type EndoTrajectoryComparisonV0,
	type EndoTrajectoryV0,
	validateEndoTrajectoryComparisonV0,
	validateEndoTrajectoryV0,
} from "../protocol/trajectory.ts";
import { canonicalEndoJsonV0, sha256HexV0 } from "../runtime/contracts/canonical-json.ts";
import { compareEndoTrajectoriesV0, endoRecordDigestV0 } from "../runtime/contracts/trajectory.ts";
import { createEndoDurableEventStoreV0 } from "../storage/event-store.ts";

const REPO = fileURLToPath(new URL("../", import.meta.url));
const REAL = "research/pi-conformance/1.0.1/lifecycle";
const FAKE = "tests/fixtures/trajectory/fake-pi";

const dirs: string[] = [];
afterAll(() => {
	for (const dir of dirs.splice(0)) rmSync(dir, { recursive: true, force: true });
});

function lines(file: string): EndoEventV0[] {
	return readFileSync(join(REPO, file), "utf8")
		.split("\n")
		.filter(Boolean)
		.map((line) => JSON.parse(line) as EndoEventV0);
}

/** The Pi session id a recording attached to. */
function piSession(events: readonly EndoEventV0[]): string {
	const attached = events.find((event) => event.kind === "harness.attached")!;
	return (attached.payload as { piSessionId: string }).piSessionId;
}

/** Load a committed recording into a scratch durable store and project it through the CLI's read-only path. */
function trajectory(directory: string, name: string): EndoTrajectoryV0 {
	const file = `${directory}/${name}.events.jsonl`;
	const events = lines(file);
	const root = mkdtempSync(join(tmpdir(), "endo-trajectory-"));
	dirs.push(root);
	const store = createEndoDurableEventStoreV0(root);
	for (const event of events) store.ingest(event);
	store.close();
	return trajectoryFromStoreV0(root, piSession(events), { label: file });
}

/** compare(b, a) predicted from compare(a, b): sides swapped, usage deltas negated, digest recomputed. */
function swapped(comparison: EndoTrajectoryComparisonV0): unknown {
	const flip = (value: unknown): unknown => {
		if (value === null || typeof value !== "object") return value;
		if (Array.isArray(value)) return value.map(flip);
		const record = value as Record<string, unknown>;
		const out = Object.fromEntries(Object.entries(record).map(([key, item]) => [key, flip(item)]));
		if ("a" in record && "b" in record) {
			// The entries themselves are swapped whole, not flipped inside.
			out.a = record.b;
			out.b = record.a;
		}
		return out;
	};
	const negate = (value: unknown): unknown => {
		if (typeof value === "number") return value === 0 ? 0 : -value;
		if (value === null || typeof value !== "object") return value;
		return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, negate(item)]));
	};
	const usage = comparison.layers.usage;
	const body = {
		...comparison,
		a: comparison.b,
		b: comparison.a,
		flags: comparison.flags.map(flip),
		layers: {
			lifecycle: flip(comparison.layers.lifecycle),
			tools: flip(comparison.layers.tools),
			outcome: flip(comparison.layers.outcome),
			usage:
				usage.status === "UNAVAILABLE"
					? flip(usage)
					: {
							status: "DELTAS",
							runs: usage.runs.map((run) => ({
								run: run.run,
								present: { a: run.present.b, b: run.present.a },
								tokens: negate(run.tokens),
								wallMs: negate(run.wallMs),
							})),
							totals: negate(usage.totals),
						},
		},
	} as Record<string, unknown>;
	return { ...body, digest: endoRecordDigestV0(body) };
}

/** Compare, and check the result's validity, determinism and symmetry before returning it. */
function compare(a: EndoTrajectoryV0, b: EndoTrajectoryV0): EndoTrajectoryComparisonV0 {
	const result = compareEndoTrajectoriesV0(a, b);
	expect(validateEndoTrajectoryComparisonV0(JSON.parse(JSON.stringify(result)), endoRecordDigestV0)).not.toBeNull();
	expect(canonicalEndoJsonV0(compareEndoTrajectoriesV0(a, b))).toBe(canonicalEndoJsonV0(result));
	expect(canonicalEndoJsonV0(compareEndoTrajectoriesV0(b, a))).toBe(canonicalEndoJsonV0(swapped(result)));
	return result;
}

function expectSelfExact(t: EndoTrajectoryV0): void {
	const result = compare(t, t);
	for (const layer of ["lifecycle", "tools", "outcome"] as const) {
		const length = t.layers[layer].status === "reported" ? t.layers[layer].entries.length : -1;
		expect(result.layers[layer]).toEqual({ status: "EXACT", length });
	}
	expect(result.flags).toEqual([]);
	if (result.layers.usage.status === "DELTAS") {
		for (const run of result.layers.usage.runs) {
			for (const value of Object.values(run.tokens ?? {})) expect(value === null || value === 0).toBe(true);
			expect(run.wallMs === null || run.wallMs === 0).toBe(true);
		}
	}
}

describe("the comparison record", () => {
	it("carries its rules verbatim, and the rules say what alignment, usage, flags and symmetry mean", () => {
		const t = trajectory(REAL, "completes");
		expect(compare(t, t).rules).toEqual(ENDO_TRAJECTORY_COMPARISON_RULES_V0);
		expect(ENDO_TRAJECTORY_COMPARISON_RULES_V0.alignment).toMatch(/position .* never by timestamp/);
		expect(ENDO_TRAJECTORY_COMPARISON_RULES_V0.usage).toMatch(/never judged EXACT or DIVERGED/);
	});

	it("rejects a tampered trajectory or comparison by digest", () => {
		const t = trajectory(REAL, "completes");
		const tampered = JSON.parse(JSON.stringify(t)) as EndoTrajectoryV0;
		(tampered.layers.outcome as { entries: { outcome: string }[] }).entries[0]!.outcome = "failed";
		expect(validateEndoTrajectoryV0(tampered, endoRecordDigestV0)).toBeNull();
		expect(() => compareEndoTrajectoriesV0(t, tampered)).toThrow(/digest/);
		const result = JSON.parse(JSON.stringify(compareEndoTrajectoriesV0(t, t)));
		result.layers.tools = { status: "EXACT", length: 7 };
		expect(validateEndoTrajectoryComparisonV0(result, endoRecordDigestV0)).toBeNull();
	});

	it("never carries raw text: tool arguments only by digest, causes only by reference", () => {
		for (const name of ["baseline", "tool-args-differ"]) {
			const text = canonicalEndoJsonV0(trajectory(FAKE, name));
			for (const raw of ["a.txt", "b.txt", '"ls"', "fake tool result", "fake reply", "hello"])
				expect(text.includes(raw)).toBe(false);
		}
	});
});

describe("REAL Pi 1.0.1 recordings (qwen3.8-27b via llama.cpp)", () => {
	it.each(["completes", "stop-mid-turn", "killed-and-resumed"])(
		"%s against itself is EXACT on every layer",
		(name) => {
			const t = trajectory(REAL, name);
			expect(t.layers.lifecycle.status).toBe("reported");
			expectSelfExact(t);
		},
	);

	it("projection is a pure function of the events: from the file, from the store, and re-parsed", () => {
		const file = `${REAL}/completes.events.jsonl`;
		const events = lines(file);
		const direct = projectPiTrajectoryV0(events, { store: file, session: piSession(events) });
		expect(canonicalEndoJsonV0(trajectory(REAL, "completes"))).toBe(canonicalEndoJsonV0(direct));
		expect(
			canonicalEndoJsonV0(
				projectPiTrajectoryV0(JSON.parse(JSON.stringify(events)), {
					store: file,
					session: `endo.session.pi.${piSession(events)}`,
				}),
			),
		).toBe(canonicalEndoJsonV0(direct));
	});

	it("completes vs stop-mid-turn: identical prefix, first divergence at the STOP, completed vs aborted", () => {
		const result = compare(trajectory(REAL, "completes"), trajectory(REAL, "stop-mid-turn"));
		expect(result.flags).toEqual([]);
		expect(result.layers.lifecycle).toMatchObject({
			status: "DIVERGED",
			index: 3,
			commonPrefix: 3,
			a: { kind: "lifecycle.turn-completed" },
			b: { kind: "lifecycle.stop-requested", facts: { runOpen: true } },
		});
		expect(result.layers.outcome).toMatchObject({
			status: "DIVERGED",
			index: 0,
			a: { outcome: "completed", stopRequested: false },
			b: { outcome: "aborted", stopRequested: true, stopReason: { status: "reported", value: "aborted" } },
		});
		expect(result.layers.tools).toEqual({ status: "EXACT", length: 0 });
		expect(result.layers.usage).toMatchObject({
			status: "DELTAS",
			runs: [{ run: 1, tokens: { input: -1608, output: -72, totalTokens: -1680 } }],
		});
		expect(result.digest).toBe("6969ce47fbce57af545b5d57a47c527384d9bed18ce50455dcb841ec5e8cb822");
	});

	it("killed-and-resumed: the interruption and the resume are in the lifecycle; two runs, interrupted then completed", () => {
		const t = trajectory(REAL, "killed-and-resumed");
		const kinds =
			t.layers.lifecycle.status === "reported" ? t.layers.lifecycle.entries.map((entry) => entry.kind) : [];
		expect(kinds).toEqual([
			"lifecycle.session-started",
			"lifecycle.run-started",
			"lifecycle.turn-started",
			"lifecycle.interrupted",
			"lifecycle.session-resumed",
			"lifecycle.run-started",
			"lifecycle.turn-started",
			"lifecycle.turn-completed",
			"lifecycle.run-completed",
			"lifecycle.detached",
		]);
		expect(t.layers.lifecycle).toMatchObject({
			entries: expect.arrayContaining([
				{
					kind: "lifecycle.interrupted",
					recognized: true,
					facts: expect.objectContaining({ cause: "observer-lost" }),
				},
				{
					kind: "lifecycle.session-resumed",
					recognized: true,
					facts: { runtime: "pi", previousEnd: "interrupted" },
				},
			]),
		});
		expect(t.layers.outcome).toMatchObject({
			entries: [
				{ run: 1, outcome: "interrupted", cause: { cause: "observer-lost" } },
				{ run: 2, outcome: "completed" },
			],
		});
		// Usage comes from the live stream only: the resumed run's one message, not again from the catch-up entries.
		expect(t.layers.usage).toMatchObject({
			entries: [
				{ run: 1, assistantMessages: 0, tokens: { status: "UNAVAILABLE" }, wallMs: { status: "UNAVAILABLE" } },
				{ run: 2, assistantMessages: 1, tokens: { status: "reported", value: { input: 40, output: 231 } } },
			],
		});
	});

	it("killed-and-resumed: catch-up duplicates create no divergence", () => {
		const file = `${REAL}/killed-and-resumed.events.jsonl`;
		const events = lines(file);
		const session = piSession(events);
		const clean = projectPiTrajectoryV0(events, { store: file, session });
		// A reconnecting catch-up re-delivers durable entries the store already holds (same ids); replay twice over.
		const entries = events.filter((event) => event.kind === "session.entry-observed");
		const noisy = projectPiTrajectoryV0([...events, ...entries, ...events], { store: file, session });
		expect(noisy.source.duplicatesIgnored).toBe(entries.length + events.length);
		expect(canonicalEndoJsonV0(noisy.layers)).toBe(canonicalEndoJsonV0(clean.layers));
		const result = compare(clean, noisy);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.layers.usage).toMatchObject({ status: "DELTAS", totals: { tokens: { input: 0, output: 0 } } });
	});

	it("the 1.0.1 recordings predate pi-rpc-mapping.3: mapping is UNAVAILABLE with the reason", () => {
		const t = trajectory(REAL, "completes");
		expect(t.environment.attachments[0]!.mapping).toEqual({
			status: "UNAVAILABLE",
			reason: "the attachment recorded no mapping version (pi-rpc-mapping.2 and earlier do not)",
		});
	});
});

describe("FAKE hostile recordings (fake Pi: proves the comparison sees each difference, not Pi behaviour)", () => {
	const baseline = () => trajectory(FAKE, "baseline");

	it("the committed files are the ones the manifest names", () => {
		const manifest = JSON.parse(readFileSync(join(REPO, FAKE, "manifest.json"), "utf8")) as {
			kind: string;
			cases: { name: string; eventsSha256: string }[];
		};
		expect(manifest.kind).toBe("fake-pi");
		for (const entry of manifest.cases) {
			const bytes = readFileSync(join(REPO, FAKE, `${entry.name}.events.jsonl`));
			expect(createHash("sha256").update(bytes).digest("hex")).toBe(entry.eventsSha256);
		}
	});

	it("baseline: two tool calls with argument digests and results, mapping recorded", () => {
		const t = baseline();
		expect(t.layers.tools).toEqual({
			status: "reported",
			entries: [
				{
					run: 1,
					turn: 1,
					name: { status: "reported", value: "read" },
					argsSha256: { status: "reported", value: piToolArgsDigestV0({ path: "a.txt" }) },
					result: { status: "reported", value: "ok" },
				},
				{
					run: 1,
					turn: 1,
					name: { status: "reported", value: "bash" },
					argsSha256: { status: "reported", value: piToolArgsDigestV0({ command: "ls" }) },
					result: { status: "reported", value: "ok" },
				},
			],
		});
		expect(t.environment.attachments[0]!.mapping).toEqual({ status: "reported", value: "pi-rpc-mapping.3" });
		expectSelfExact(t);
	});

	it("a second recording of the same behaviour is EXACT on every judged layer (ids, timestamps differ)", () => {
		const result = compare(baseline(), trajectory(FAKE, "baseline-again"));
		expect(result.a.eventsSha256).not.toBe(result.b.eventsSha256);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.flags).toEqual([]);
		expect(result.digest).toBe("ee8bd43ff1897608dd7addd64a5003e125049bcdbbaebd93c8ba1f8fbab4af6c");
	});

	it("reordered tool calls diverge at the first call; lifecycle and outcome stay EXACT", () => {
		const result = compare(baseline(), trajectory(FAKE, "tools-reordered"));
		expect(result.layers.tools).toMatchObject({
			status: "DIVERGED",
			index: 0,
			commonPrefix: 0,
			a: { name: { value: "read" } },
			b: { name: { value: "bash" } },
		});
		expect(result.layers.lifecycle.status).toBe("EXACT");
		expect(result.layers.outcome.status).toBe("EXACT");
		expect(result.digest).toBe("661e17c816107e01b1ea0d1a8812d13fe3b8f1df45f8a4f011ec304c078097a7");
	});

	it("the same tool with different arguments diverges by argument digest", () => {
		const result = compare(baseline(), trajectory(FAKE, "tool-args-differ"));
		expect(result.layers.tools).toMatchObject({
			status: "DIVERGED",
			index: 0,
			a: { name: { value: "read" }, argsSha256: { value: piToolArgsDigestV0({ path: "a.txt" }) } },
			b: { name: { value: "read" }, argsSha256: { value: piToolArgsDigestV0({ path: "b.txt" }) } },
		});
		expect(result.digest).toBe("d468e5201e6cae53d693f418821fdc8e83b3ddaae46cb6de582b49caaafbca5b");
	});

	it("a tool result status difference diverges at that call", () => {
		const result = compare(baseline(), trajectory(FAKE, "tool-errors"));
		expect(result.layers.tools).toMatchObject({
			status: "DIVERGED",
			index: 1,
			commonPrefix: 1,
			a: { result: { value: "ok" } },
			b: { result: { value: "error" } },
		});
		expect(result.digest).toBe("9992af8edb7dd09c3a2a8320649acc086ada859df10f3fe5894a9fdd75eaed49");
	});

	it("one side missing usage: usage is UNAVAILABLE for that side, the judged layers are unaffected", () => {
		const result = compare(baseline(), trajectory(FAKE, "no-usage"));
		expect(result.layers.usage).toEqual({
			status: "UNAVAILABLE",
			a: null,
			b: "Pi reported no usage on any assistant message of this session",
		});
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.digest).toBe("3abe05624652fa83d7e8ac04a060572c20d999ef57dc62062082de06963ed74c");
	});

	it("an unknown runtime lifecycle record is a lifecycle divergence where it appeared", () => {
		const result = compare(baseline(), trajectory(FAKE, "unknown-lifecycle"));
		expect(result.layers.lifecycle).toMatchObject({
			status: "DIVERGED",
			index: 2,
			a: { kind: "lifecycle.turn-started" },
			b: { kind: "lifecycle.unrecognized-runtime-event", facts: { runtimeEvent: "agent_paused" } },
		});
		expect(result.layers.tools.status).toBe("EXACT");
		expect(result.digest).toBe("dce89cd274b9c1def9005bd2411a02699999ad441abe024a2b6a4e0d71ab45b5");
	});

	it("an undefined lifecycle.* kind is kept, unrecognized, by payload digest, and diverges", () => {
		// Hand-made, not fake-Pi output: a lifecycle kind from a future fold, inserted after run-started.
		const file = `${FAKE}/baseline.events.jsonl`;
		const events = lines(file);
		const at = events.findIndex((event) => event.kind === "lifecycle.run-started");
		const future: EndoEventV0 = {
			...events[at]!,
			id: "endo.event.pi-lifecycle.future-kind",
			kind: "lifecycle.run-paused",
			payload: { why: "future" },
		};
		const withFuture = [...events.slice(0, at + 1), future, ...events.slice(at + 1)];
		const t = projectPiTrajectoryV0(withFuture, { store: file, session: piSession(events) });
		expect(t.layers.lifecycle).toMatchObject({
			entries: expect.arrayContaining([
				{
					kind: "lifecycle.run-paused",
					recognized: false,
					facts: { payloadSha256: sha256HexV0(canonicalEndoJsonV0({ why: "future" })) },
				},
			]),
		});
		const result = compare(projectPiTrajectoryV0(events, { store: file, session: piSession(events) }), t);
		expect(result.layers.lifecycle).toMatchObject({
			status: "DIVERGED",
			index: 2,
			b: { kind: "lifecycle.run-paused" },
		});
	});

	it("different fingerprints are allowed but flagged; the verdicts are unchanged", () => {
		const result = compare(baseline(), trajectory(FAKE, "other-fingerprint"));
		expect(result.flags.map((flag) => flag.kind)).toEqual(["runtime-fingerprint-differs", "runtime-version-differs"]);
		expect(result.flags[1]).toEqual({ kind: "runtime-version-differs", a: ["1.0.0"], b: ["1.0.1"] });
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.digest).toBe("436cae28cd27c9e0d7384258fd078eaa37083f266390bc6152b13b6d42933f7c");
	});

	it("real vs fake: model, mapping and fingerprint differences are all flagged, never mixed silently", () => {
		const result = compare(trajectory(REAL, "completes"), baseline());
		expect(result.flags.map((flag) => flag.kind)).toEqual([
			"runtime-fingerprint-differs",
			"runtime-version-differs",
			"mapping-differs",
			"configuration-differs",
			"configured-model-differs",
			"reported-model-differs",
		]);
	});

	it("an argument digest the recording did not capture leaves the tool layer UNAVAILABLE, not EXACT", () => {
		const file = `${FAKE}/baseline.events.jsonl`;
		const events = lines(file);
		const stripped = events.map((event) =>
			event.kind === "tool.started"
				? { ...event, payload: { ...(event.payload as Record<string, unknown>), argsSha256: undefined } }
				: event,
		);
		const old = projectPiTrajectoryV0(JSON.parse(JSON.stringify(stripped)), {
			store: file,
			session: piSession(events),
		});
		const result = compare(old, projectPiTrajectoryV0(events, { store: file, session: piSession(events) }));
		expect(result.layers.tools).toEqual({
			status: "UNAVAILABLE",
			a: null,
			b: null,
			unverified: [0, 1],
			lengths: { a: 2, b: 2 },
		});
	});
});

describe("endo trajectory show / diff", () => {
	function capture(run: () => void): string {
		let out = "";
		const spy = vi.spyOn(process.stdout, "write").mockImplementation((chunk) => {
			out += String(chunk);
			return true;
		});
		try {
			run();
		} finally {
			spy.mockRestore();
		}
		return out;
	}

	function store(name: string): { root: string; session: string } {
		const events = lines(`${REAL}/${name}.events.jsonl`);
		const root = mkdtempSync(join(tmpdir(), "endo-trajectory-cli-"));
		dirs.push(root);
		const created = createEndoDurableEventStoreV0(root);
		for (const event of events) created.ingest(event);
		created.close();
		return { root, session: piSession(events) };
	}

	it("print one canonical-JSON document each and change nothing on disk", () => {
		const a = store("completes");
		const b = store("stop-mid-turn");
		const log = join(a.root, "events", "events.log");
		const before = readFileSync(log);
		const shown = capture(() => trajectoryShowCommand([a.root, a.session]));
		expect(canonicalEndoJsonV0(JSON.parse(shown))).toBe(shown);
		expect(validateEndoTrajectoryV0(JSON.parse(shown), endoRecordDigestV0)).not.toBeNull();
		const diff = capture(() => trajectoryDiffCommand([a.root, a.session, b.root, `endo.session.pi.${b.session}`]));
		expect(canonicalEndoJsonV0(JSON.parse(diff))).toBe(diff);
		expect(JSON.parse(diff).layers.lifecycle.index).toBe(3);
		expect(readFileSync(log).equals(before)).toBe(true);
	});

	it("name the recorded sessions when the requested one is not there", () => {
		const a = store("completes");
		expect(() => trajectoryShowCommand([a.root, "no-such-session"])).toThrow(
			new RegExp(`recorded sessions: endo\\.session\\.pi\\.${a.session}`),
		);
		expect(() => trajectoryShowCommand([a.root])).toThrow(/usage/);
		expect(() => trajectoryShowCommand([a.root, a.session, "--bogus", "x"])).toThrow(/unknown flag/);
	});
});

describe("REAL Pi 1.0.1 completes-repeat (a preliminary observation, not a variance result)", () => {
	const REPEAT = "research/pi-conformance/1.0.1/completes-repeat";

	it("the committed files are the ones each provenance names, recorded under pi-rpc-mapping.3", () => {
		for (const run of ["run-1", "run-2"]) {
			const provenance = JSON.parse(readFileSync(join(REPO, REPEAT, run, "provenance.json"), "utf8"));
			expect(provenance).toMatchObject({ kind: "real", endophasia: { mapping: "pi-rpc-mapping.3" } });
			expect(provenance.sessions.map((session: { name: string }) => session.name)).toEqual(["completes"]);
			const bytes = readFileSync(join(REPO, REPEAT, run, "completes.events.jsonl"));
			expect(createHash("sha256").update(bytes).digest("hex")).toBe(provenance.sessions[0].eventsSha256);
		}
	});

	it("run-1 vs run-2: EXACT on every judged layer, no flags, usage reported as deltas only", () => {
		const result = compare(trajectory(`${REPEAT}/run-1`, "completes"), trajectory(`${REPEAT}/run-2`, "completes"));
		expect(result.flags).toEqual([]);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.layers.usage).toMatchObject({
			status: "DELTAS",
			totals: { tokens: { input: 3, output: -5, cacheRead: 0 }, wallMs: 36 },
		});
		expect(result.digest).toBe("277aee9428260e2a8410ff906b0ba3479235d39c70812e9033f39056ec235e04");
	});

	it.each(["run-1", "run-2"])("the committed lifecycle completes vs %s: EXACT, flagged mapping-differs", (run) => {
		const result = compare(trajectory(REAL, "completes"), trajectory(`${REPEAT}/${run}`, "completes"));
		expect(result.flags).toEqual([{ kind: "mapping-differs", a: [null], b: ["pi-rpc-mapping.3"] }]);
		for (const layer of ["lifecycle", "tools", "outcome"] as const) expect(result.layers[layer].status).toBe("EXACT");
		expect(result.layers.usage).toMatchObject({ status: "DELTAS", totals: { tokens: { cacheRead: 1476 } } });
	});
});

describe("argument digests (pi-rpc-mapping.3)", () => {
	it("are the sha256 of the arguments' canonical JSON: key order does not matter, values do", () => {
		const digest = piToolArgsDigestV0({ path: "a.txt", limit: 2 });
		expect(digest).toBe(sha256HexV0(canonicalEndoJsonV0({ limit: 2, path: "a.txt" })));
		expect(piToolArgsDigestV0({ limit: 2, path: "a.txt" })).toBe(digest);
		expect(piToolArgsDigestV0({ path: "a.txt", limit: 3 })).not.toBe(digest);
		expect(piToolArgsDigestV0(undefined)).toBeUndefined();
	});
});

describe("the recorder's --sessions subset", () => {
	it("is refused for a version's lifecycle directory, so a full fixture is never replaced by a subset", async () => {
		const { recordPiLifecycleFixturesV0 } = await import("../scripts/record-lifecycle-fixture.ts");
		const { installFakePi } = await import("./fixtures/fake-pi/install.ts");
		const install = installFakePi("1.0.0");
		const out = mkdtempSync(join(tmpdir(), "endo-subset-"));
		dirs.push(out);
		try {
			await expect(
				recordPiLifecycleFixturesV0({
					pi: install.bin,
					baseUrl: null,
					model: "fake-1",
					providerName: "fake",
					apiKeyEnv: null,
					out: join(out, "pi-conformance", "1.0.0", "lifecycle"),
					authorizeLiveStudy: false,
					timeoutMs: 20_000,
					kind: "fake-pi",
					sessions: ["completes"],
					log: () => {},
				}),
			).rejects.toThrow(/full lifecycle fixture; record a subset of sessions elsewhere/);
		} finally {
			install.remove();
		}
	});
});
